from typing import List

class Solution:
    def canSeePersonsCount(self, heights: List[int]) -> List[int]:
        n = len(heights)
        ans = [0] * n
        for i in range(n):
            for j in range(i + 1, n):
                limit = min(heights[i], heights[j])
                visible = True
                for k in range(i + 1, j):
                    if heights[k] >= limit:
                        visible = False
                        break
                if visible:
                    ans[i] += 1
        return ans

